package dev.underthebedrock.horror;
import dev.underthebedrock.UnderTheBedrockPlugin;import dev.underthebedrock.world.VoidWorldManager;
import org.bukkit.ChatColor;import org.bukkit.Material;import org.bukkit.Sound;import org.bukkit.block.Block;import org.bukkit.block.Sign;import org.bukkit.entity.Player;import org.bukkit.event.EventHandler;import org.bukkit.event.Listener;import org.bukkit.event.block.Action;import org.bukkit.event.player.PlayerInteractEvent;import org.bukkit.persistence.PersistentDataType;import org.bukkit.NamespacedKey;import org.bukkit.scheduler.BukkitTask;
import java.util.Random;
/** Deterministic, chunk-safe evidence sites with per-player discovery and a persistent clue chain. */
public final class ClueManager implements Listener {
 private static final int CELL=1024;private final UnderTheBedrockPlugin plugin;private final VoidWorldManager worlds;private final OccurrenceDirector director;private final NamespacedKey clueKey;private BukkitTask task;
 public ClueManager(UnderTheBedrockPlugin p,VoidWorldManager w,OccurrenceDirector d){plugin=p;worlds=w;director=d;clueKey=new NamespacedKey(p,"evidence-clue");}
 public void start(){if(task!=null)return;plugin.getServer().getPluginManager().registerEvents(this,plugin);long interval=Math.max(20,plugin.getConfig().getLong("horror.clues.scan-interval-ticks",100));task=plugin.getServer().getScheduler().runTaskTimer(plugin,this::tick,40L,interval);}
 public void stop(){if(task!=null)task.cancel();task=null;}
 private void tick(){if(!worlds.isActive())return;var world=worlds.getWorld();if(world==null)return;for(Player p:world.getPlayers()){int cx=Math.floorDiv(p.getLocation().getBlockX()-world.getSpawnLocation().getBlockX(),CELL),cz=Math.floorDiv(p.getLocation().getBlockZ()-world.getSpawnLocation().getBlockZ(),CELL);for(int x=cx-1;x<=cx+1;x++)for(int z=cz-1;z<=cz+1;z++)ensureSite(world,x,z);}}
 private void ensureSite(org.bukkit.World world,int cellX,int cellZ){long seed=world.getSeed()^((long)cellX*0x9E3779B97F4A7C15L)^((long)cellZ*0xC2B2AE3D27D4EB4FL);Random r=new Random(seed);int ox=cellX*CELL+CELL/2+r.nextInt(241)-120,oz=cellZ*CELL+CELL/2+r.nextInt(241)-120;int minimum=plugin.getConfig().getInt("horror.clues.minimum-distance-blocks",768);double distance=Math.hypot(ox,oz);if(distance<minimum){double scale=(minimum+128.0)/Math.max(1,distance);ox=(int)Math.round(ox*scale);oz=(int)Math.round(oz*scale);distance=Math.hypot(ox,oz);}ClueDefinition clue=ClueDefinition.forSite(distance,seed).orElse(null);if(clue==null)return;var origin=world.getSpawnLocation();int x=origin.getBlockX()+ox,z=origin.getBlockZ()+oz,y=plugin.getConfig().getInt("world.floor-y",64);if(!world.isChunkLoaded(Math.floorDiv(x,16),Math.floorDiv(z,16)))return;
  for(int dx=-1;dx<=1;dx++)for(int dz=-1;dz<=1;dz++)if(!world.isChunkLoaded(Math.floorDiv(x+dx,16),Math.floorDiv(z+dz,16)))return;
  Block signBlock=world.getBlockAt(x,y+2,z);if(signBlock.getType()!=Material.AIR)return;for(int dx=-1;dx<=1;dx++)for(int dz=-1;dz<=1;dz++)if(world.getBlockAt(x+dx,y+1,z+dz).getType()!=Material.AIR)return;
  for(int dx=-1;dx<=1;dx++)for(int dz=-1;dz<=1;dz++)world.getBlockAt(x+dx,y+1,z+dz).setType(dx==0&&dz==0?Material.CRYING_OBSIDIAN:Material.POLISHED_BLACKSTONE_BRICKS,false);
  signBlock.setType(Material.OAK_SIGN,false);if(signBlock.getState() instanceof Sign sign){sign.setLine(0,ChatColor.DARK_GRAY+"[EVIDENCE]");sign.setLine(1,ChatColor.BLACK+clue.title());sign.setLine(2,ChatColor.GRAY+"Right-click");sign.setLine(3,ChatColor.DARK_GRAY+"to examine");sign.getPersistentDataContainer().set(clueKey,PersistentDataType.STRING,clue.id());sign.update(true,false);}}
 @EventHandler public void onEvidenceInteract(PlayerInteractEvent event){if(event.getHand()!=org.bukkit.inventory.EquipmentSlot.HAND)return;if(event.getAction()!=Action.RIGHT_CLICK_BLOCK||event.getClickedBlock()==null)return;Player p=event.getPlayer();if(!worlds.isActive()||!p.getWorld().equals(worlds.getWorld()))return;if(!(event.getClickedBlock().getState() instanceof Sign sign))return;String id=sign.getPersistentDataContainer().get(clueKey,PersistentDataType.STRING);if(id==null)return;event.setCancelled(true);ClueDefinition clue=ClueDefinition.byId(id).orElse(null);if(clue==null)return;PlayerHorrorMemory memory=director.memory(p.getUniqueId());if(memory.hasClue(id)){p.sendMessage(ChatColor.DARK_GRAY+"You have already recorded this evidence.");p.sendMessage(ChatColor.GRAY+"§o"+clue.text());return;}if(!clue.prerequisiteMet(memory)){p.sendMessage(ChatColor.DARK_GRAY+"The words refuse to arrange themselves into anything meaningful.");p.playSound(p.getLocation(),Sound.BLOCK_NOTE_BLOCK_BASS,.3f,.65f);return;}memory.discoverClue(id,System.currentTimeMillis());director.saveMemory(p.getUniqueId());p.sendMessage("");p.sendMessage(ChatColor.DARK_GRAY+"§lEVIDENCE RECORDED: "+ChatColor.GRAY+clue.title());p.sendMessage(ChatColor.GRAY+"§o"+clue.text());p.sendMessage(ChatColor.DARK_GRAY+"Evidence: "+memory.discoveredClueCount()+"/"+ClueDefinition.values().length);p.playSound(p.getLocation(),Sound.BLOCK_AMETHYST_BLOCK_CHIME,.45f,.7f);Block pedestal=event.getClickedBlock().getWorld().getBlockAt(event.getClickedBlock().getX(),plugin.getConfig().getInt("world.floor-y",64)+1,event.getClickedBlock().getZ());if(pedestal.getType()==Material.CRYING_OBSIDIAN)pedestal.setType(Material.AMETHYST_BLOCK,false);}
}